CGEN.g_median=function(){var n=cP([7,9,11]),v=[];for(var i=0;i<n;i++)v.push(cR(2,40));var s=v.slice().sort(function(a,b){return a-b});
 if(cR(0,2)<2||n===9){var md=s[(n-1)/2];return {p:'Find the median of: '+v.join(', ')+'.',b:[cB(md,'median = ','','median')],e:'Put them in order: '+s.join(', ')+'. There are '+n+' values, so the median is value number '+((n+1)/2)+': '+md+'.'}}
 var q1=s[(n+1)/4-1],q3=s[3*(n+1)/4-1];return {p:'Find the interquartile range of: '+v.join(', ')+'.',b:[cB(q3-q1,'IQR = ','','IQR')],e:'In order: '+s.join(', ')+'. With '+n+' values, the lower quartile is value number '+((n+1)/4)+' ('+q1+') and the upper quartile is value number '+(3*(n+1)/4)+' ('+q3+'). IQR = '+q3+' − '+q1+' = '+(q3-q1)+'.'}};
